-- WORDLESS v2 P10 — SEO audit runs (Lighthouse / structured-data check
-- results, timestamped). Audit history only: scores are recorded here
-- exactly as a real tool measured them, never generated by the Worker.
-- A run with NULL scores is a manual/partial record (e.g. a
-- structured-data-only check); the admin UI shows "not measured" for
-- NULLs rather than inventing a number.
CREATE TABLE IF NOT EXISTS wl_seo_audit_runs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL,
    tool TEXT NOT NULL DEFAULT 'lighthouse',
    seo_score INTEGER,
    accessibility_score INTEGER,
    performance_score INTEGER,
    best_practices_score INTEGER,
    lcp_ms INTEGER,
    inp_ms INTEGER,
    cls_milli REAL,
    notes TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_seo_audit_runs_url ON wl_seo_audit_runs (url);
CREATE INDEX IF NOT EXISTS idx_seo_audit_runs_created ON wl_seo_audit_runs (created_at);
